using Habitica.Application.Workspace;
using Habitica.Domain.Workspace;
namespace Habitica.Application.Tests.Workspace;

public sealed class WorkspaceActivityStreakTests
{
    private static DateTimeOffset At(string value)=>DateTimeOffset.Parse(value,System.Globalization.CultureInfo.InvariantCulture);
    private static WorkspaceJournalSnapshot Apply(WorkspaceJournalSnapshot state,WorkspaceOperation operation,string at,WorkspaceTaskPatch? patch=null,DateOnly? day=null,HabitScoreDirection? direction=null,int count=1)
    {
        var id=state.Document.Tasks.FirstOrDefault()?.Id??Guid.NewGuid();var command=new WorkspaceCommand(Guid.NewGuid(),state.Document.Id,state.Document.Revision,operation,id,patch,direction,count,OccurrenceDate:day);var result=WorkspaceCommandEngine.Accept(state,command,At(at));Assert.Equal(SubmissionDisposition.Accepted,result.Disposition);Assert.True(WorkspaceJournalValidation.IsValid(result.Snapshot!));return result.Snapshot!;
    }
    private static WorkspaceJournalSnapshot Start(CompanionTaskKind kind=CompanionTaskKind.Daily,string zone="UTC",string day="2026-10-27",HabiticaTaskDetails? details=null)
    {
        var state=new WorkspaceJournalSnapshot(new(){Id=Guid.NewGuid()},1,[],[]);return Apply(state,kind==CompanionTaskKind.Daily?WorkspaceOperation.CreateDaily:WorkspaceOperation.CreateHabit,day+"T00:00:00Z",new(Text:"Synthetic activity",Recurrence:kind==CompanionTaskKind.Daily?new(RecurrenceFrequency.Daily,1,DateOnly.Parse(day),zone,[],[]):null,HabiticaDetails:details));
    }
    [Fact]public void Scheduled_Daily_days_and_current_unfinished_day_preserve_the_verified_previous_run()
    {
        var state=Start();state=Apply(state,WorkspaceOperation.CompleteTask,"2026-10-27T12:00:00Z",day:new(2026,10,27));state=Apply(state,WorkspaceOperation.CompleteTask,"2026-10-28T12:00:00Z",day:new(2026,10,28));state=Apply(state,WorkspaceOperation.UpdateTask,"2026-10-29T00:00:00Z",new(Text:"Actual tail witness"));var before=WorkspaceJournalJson.Serialize(state);
        var result=WorkspaceActivityStreaks.Evaluate(state,new(state.Document.Tasks[0].Id,new(2026,10,27),At("2026-10-29T12:00:00Z"),"UTC"));Assert.Equal(2,result.CurrentStreak);Assert.Equal("verified",result.CurrentQuality);Assert.Equal(2,result.LongestObserved);Assert.Equal(new[]{"completed","completed","pending"},result.Items.Select(d=>d.Status));Assert.Equal(before,WorkspaceJournalJson.Serialize(state));
    }
    private static ActivityStreakFilter Filter(WorkspaceJournalSnapshot state,string from,string asOf,string zone="UTC")=>new(state.Document.Tasks[0].Id,DateOnly.Parse(from),At(asOf),zone);
    private sealed record Example(string Name,WorkspaceJournalSnapshot Snapshot,ActivityStreakFilter Filter,int? Current,string Quality,int Longest,string[] Statuses,int Positive,int Negative);
