        yield return new("habit-positive-days-deduplicate-and-negative-events-stay-separate",habit,Filter(habit,"2026-10-27","2026-10-29T12:00:00Z"),2,"verified",2,["positive","positive","pending"],3,2);
        var legacy=habit with{Document=habit.Document with{ActivityCoverage=null}};yield return new("legacy-positive-evidence-retains-a-lower-bound",legacy,Filter(legacy,"2026-10-27","2026-10-29T12:00:00Z"),2,"lowerBound",2,["positive","positive","pending"],3,2);
        var gap=Start(CompanionTaskKind.Habit);gap=Apply(gap,WorkspaceOperation.ScoreHabit,"2026-10-27T12:00:00Z",direction:HabitScoreDirection.Up);gap=Apply(gap,WorkspaceOperation.ScoreHabit,"2026-10-29T12:00:00Z",direction:HabitScoreDirection.Up);gap=Apply(gap,WorkspaceOperation.UpdateTask,"2026-10-30T00:00:00Z",new(Text:"tail"));
        yield return new("known-inactivity-breaks-the-run",gap,Filter(gap,"2026-10-27","2026-10-30T12:00:00Z"),1,"verified",1,["positive","missed","positive","pending"],2,0);
