        var paused=Start(CompanionTaskKind.Habit);paused=Apply(paused,WorkspaceOperation.ScoreHabit,"2026-10-27T12:00:00Z",direction:HabitScoreDirection.Up);paused=Apply(paused,WorkspaceOperation.PauseTask,"2026-10-28T00:00:00Z");paused=Apply(paused,WorkspaceOperation.ResumeTask,"2026-10-29T00:00:00Z");paused=Apply(paused,WorkspaceOperation.ScoreHabit,"2026-10-29T12:00:00Z",direction:HabitScoreDirection.Up);paused=Apply(paused,WorkspaceOperation.UpdateTask,"2026-10-30T00:00:00Z",new(Text:"tail"));
        yield return new("paused-interval-is-neutral",paused,Filter(paused,"2026-10-27","2026-10-30T12:00:00Z"),2,"verified",2,["positive","neutral","positive","pending"],2,0);
