        yield return new("negative-only-habit-is-frequency-not-positive-streak",negative,Filter(negative,"2026-10-27","2026-10-29T12:00:00Z"),null,"notApplicable",0,["activity","activity","pending"],0,3);
        var changedGoal=Start(CompanionTaskKind.Habit,details:new(Up:false,Down:true));changedGoal=Apply(changedGoal,WorkspaceOperation.ScoreHabit,"2026-10-27T12:00:00Z",direction:HabitScoreDirection.Down);changedGoal=Apply(changedGoal,WorkspaceOperation.UpdateTask,"2026-10-28T00:00:00Z",new(HabiticaDetails:new(Up:true)));changedGoal=Apply(changedGoal,WorkspaceOperation.ScoreHabit,"2026-10-28T12:00:00Z",direction:HabitScoreDirection.Up);changedGoal=Apply(changedGoal,WorkspaceOperation.UpdateTask,"2026-10-29T00:00:00Z",new(Text:"tail"));
        yield return new("historical-negative-only-days-never-become-positive-goal-failures",changedGoal,Filter(changedGoal,"2026-10-27","2026-10-29T12:00:00Z"),1,"verified",1,["neutral","positive","pending"],1,1);
        yield return new("historical-asof-uses-the-direction-goal-effective-at-that-time",changedGoal,Filter(changedGoal,"2026-10-27","2026-10-27T23:00:00Z"),null,"notApplicable",0,["activity"],0,1);
        var daily=Start();daily=Apply(daily,WorkspaceOperation.CompleteTask,"2026-10-27T12:00:00Z",day:new(2026,10,27));daily=Apply(daily,WorkspaceOperation.SkipOccurrence,"2026-10-28T12:00:00Z",day:new(2026,10,28));daily=Apply(daily,WorkspaceOperation.CompleteTask,"2026-10-29T12:00:00Z",day:new(2026,10,29));daily=Apply(daily,WorkspaceOperation.UpdateTask,"2026-10-30T00:00:00Z",new(Text:"tail"));
        yield return new("skipped-scheduled-day-is-neutral",daily,Filter(daily,"2026-10-27","2026-10-30T12:00:00Z"),2,"verified",2,["completed","neutral","completed","pending"],2,0);
        var schedule=Start();schedule=Apply(schedule,WorkspaceOperation.CompleteTask,"2026-10-27T12:00:00Z",day:new(2026,10,27));schedule=Apply(schedule,WorkspaceOperation.UpdateTask,"2026-10-28T00:00:00Z",new(Recurrence:new(RecurrenceFrequency.Daily,2,new(2026,10,29),"UTC",[],[])));schedule=Apply(schedule,WorkspaceOperation.CompleteTask,"2026-10-29T12:00:00Z",day:new(2026,10,29));schedule=Apply(schedule,WorkspaceOperation.UpdateTask,"2026-10-30T00:00:00Z",new(Text:"tail"));
        yield return new("historical-schedule-does-not-copy-the-current-start-backwards",schedule,Filter(schedule,"2026-10-27","2026-10-30T12:00:00Z"),2,"verified",2,["completed","neutral","completed","pending"],2,0);
        var corrected=Start();corrected=Apply(corrected,WorkspaceOperation.CompleteTask,"2026-10-27T12:00:00Z",day:new(2026,10,27));var occurrence=corrected.Document.Occurrences[0];corrected=Apply(corrected,WorkspaceOperation.CorrectOccurrence,"2026-10-28T00:00:00Z",new(CorrectOccurrence:new(occurrence.Id,occurrence.Revision,occurrence.TerminalCommandId!.Value)));corrected=Apply(corrected,WorkspaceOperation.UpdateTask,"2026-10-29T00:00:00Z",new(Text:"tail"));
        yield return new("later-correction-cannot-rewrite-an-earlier-asof",corrected,Filter(corrected,"2026-10-27","2026-10-27T23:00:00Z"),1,"verified",1,["completed"],1,0);
        yield return new("corrected-terminal-no-longer-counts-as-completed",corrected,Filter(corrected,"2026-10-27","2026-10-29T12:00:00Z"),0,"verified",0,["missed","missed","pending"],0,0);
        var duplicate=Apply(corrected,WorkspaceOperation.CompleteTask,"2026-10-29T12:00:00Z",day:new(2026,10,27));
        yield return new("retained-completions-after-correction-count-one-current-day",duplicate,Filter(duplicate,"2026-10-27","2026-10-29T13:00:00Z"),0,"verified",1,["completed","missed","pending"],1,0);
        var spring=Start(CompanionTaskKind.Habit,day:"2026-03-06");spring=Apply(spring,WorkspaceOperation.ScoreHabit,"2026-03-08T04:30:00Z",direction:HabitScoreDirection.Up);spring=Apply(spring,WorkspaceOperation.ScoreHabit,"2026-03-08T07:30:00Z",direction:HabitScoreDirection.Up);spring=Apply(spring,WorkspaceOperation.ScoreHabit,"2026-03-09T03:30:00Z",direction:HabitScoreDirection.Up);spring=Apply(spring,WorkspaceOperation.UpdateTask,"2026-03-09T04:00:00Z",new(Text:"tail"));
        yield return new("spring-dst-calendar-days-have-twenty-three-hours",spring,Filter(spring,"2026-03-06","2026-03-09T12:00:00Z","America/New_York"),2,"verified",2,["missed","positive","positive","pending"],3,0);
        var fall=Start(CompanionTaskKind.Habit,day:"2026-10-31");fall=Apply(fall,WorkspaceOperation.ScoreHabit,"2026-11-01T05:30:00Z",direction:HabitScoreDirection.Up);fall=Apply(fall,WorkspaceOperation.ScoreHabit,"2026-11-01T06:30:00Z",direction:HabitScoreDirection.Up);fall=Apply(fall,WorkspaceOperation.UpdateTask,"2026-11-02T05:00:00Z",new(Text:"tail"));
        yield return new("fall-dst-fold-deduplicates-one-calendar-day",fall,Filter(fall,"2026-10-31","2026-11-02T12:00:00Z","America/New_York"),1,"verified",1,["missed","positive","pending"],2,0);
        var zoned=Start();zoned=Apply(zoned,WorkspaceOperation.CompleteTask,"2026-10-27T12:00:00Z",day:new(2026,10,27));zoned=Apply(zoned,WorkspaceOperation.UpdateTask,"2026-10-28T00:00:00Z",new(Recurrence:new(RecurrenceFrequency.Daily,1,new(2026,10,27),"Europe/Prague",[],[])));zoned=Apply(zoned,WorkspaceOperation.CompleteTask,"2026-10-28T12:00:00Z",day:new(2026,10,28));zoned=Apply(zoned,WorkspaceOperation.UpdateTask,"2026-10-29T00:00:00Z",new(Text:"tail"));
        yield return new("historical-terminal-timezone-is-never-reinterpreted-as-the-requested-zone",zoned,Filter(zoned,"2026-10-27","2026-10-29T12:00:00Z"),null,"unavailable",1,["completed","unknown","pending"],1,0);
        var monthly=Start(day:"2026-01-30");monthly=Apply(monthly,WorkspaceOperation.UpdateTask,"2026-01-30T00:00:00Z",new(Recurrence:new(RecurrenceFrequency.Monthly,1,new(2026,1,31),"UTC",[],[31])));monthly=Apply(monthly,WorkspaceOperation.CompleteTask,"2026-01-31T12:00:00Z",day:new(2026,1,31));monthly=Apply(monthly,WorkspaceOperation.CompleteTask,"2026-03-31T12:00:00Z",day:new(2026,3,31));monthly=Apply(monthly,WorkspaceOperation.UpdateTask,"2026-04-01T00:00:00Z",new(Text:"tail"));var monthlyStatuses=Enumerable.Range(0,62).Select(n=>n==1||n==60?"completed":n==61?"pending":"neutral").ToArray();
        yield return new("monthly-missing-day-is-neutral-not-a-calendar-miss",monthly,Filter(monthly,"2026-01-30","2026-04-01T12:00:00Z"),2,"verified",2,monthlyStatuses,2,0);
