    [Fact]public void Independent_day_and_coverage_examples_have_exact_retained_counts_and_no_lifetime_claim()
    {
        var examples=Examples().ToArray();foreach(var e in examples){var before=WorkspaceJournalJson.Serialize(e.Snapshot);var result=WorkspaceActivityStreaks.Evaluate(e.Snapshot,e.Filter with{Limit=100});Assert.True(result.CurrentStreak==e.Current,e.Name+" current: "+result.CurrentStreak);Assert.Equal(e.Quality,result.CurrentQuality);Assert.Equal(e.Longest,result.LongestObserved);Assert.True(e.Statuses.SequenceEqual(result.Items.Select(d=>d.Status)),e.Name+": "+string.Join(",",result.Items.Select(d=>d.Status)));Assert.Equal(e.Positive,result.PositiveEvents);Assert.Equal(e.Negative,result.NegativeEvents);Assert.Null(result.LifetimeBest);Assert.Equal(before,WorkspaceJournalJson.Serialize(e.Snapshot));Assert.All(e.Snapshot.Commands,c=>Assert.Empty(c.Effects));}
        var export=Environment.GetEnvironmentVariable("HABITICA_STREAK_EXPORT");if(!string.IsNullOrEmpty(export)){var options=new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web){WriteIndented=true};var rows=examples.Select(e=>new{name=e.Name,snapshot=System.Text.Json.JsonSerializer.Deserialize<System.Text.Json.JsonElement>(WorkspaceJournalJson.Serialize(e.Snapshot)),request=new{taskId=e.Filter.TaskId,fromDay=e.Filter.FromDay.ToString("yyyy-MM-dd"),asOfUtc=e.Filter.AsOfUtc.UtcDateTime.ToString("yyyy-MM-dd'T'HH:mm:ss.fffffff'Z'"),timeZoneId=e.Filter.TimeZoneId,limit=100},expected=WorkspaceActivityStreaks.Evaluate(e.Snapshot,e.Filter with{Limit=100})});File.WriteAllText(export,System.Text.Json.JsonSerializer.Serialize(new{cases=rows},options)+"\n");}
    }
    [Fact]public void Paging_binds_revision_and_explicit_evaluation_context_and_unavailable_inputs_refuse()
    {
        var state=Start(CompanionTaskKind.Habit);state=Apply(state,WorkspaceOperation.UpdateTask,"2026-10-30T00:00:00Z",new(Text:"tail"));var filter=Filter(state,"2026-10-27","2026-10-30T12:00:00Z") with{Limit=2};var a=WorkspaceActivityStreaks.Evaluate(state,filter);Assert.Equal(2,a.Items.Count);Assert.Equal(2,a.NextOffset);var b=WorkspaceActivityStreaks.Evaluate(state,filter with{Offset=2,ExpectedRevision=a.Revision,ExpectedContext=a.Context});Assert.Equal(2,b.Items.Count);Assert.Null(b.NextOffset);Assert.Equal(a.Context,b.Context);
        Assert.Throws<InvalidOperationException>(()=>WorkspaceActivityStreaks.Evaluate(state,filter with{Offset=2,ExpectedRevision=a.Revision,ExpectedContext=a.Context,AsOfUtc=filter.AsOfUtc.AddDays(1)}));Assert.Throws<ArgumentException>(()=>WorkspaceActivityStreaks.Evaluate(state,filter with{TimeZoneId="Mars/Olympus"}));Assert.Throws<ArgumentException>(()=>WorkspaceActivityStreaks.Evaluate(state,filter with{TaskId=Guid.NewGuid()}));Assert.Throws<InvalidOperationException>(()=>WorkspaceActivityStreaks.Evaluate(state,filter with{ExpectedRevision=state.Document.Revision+1}));
    }

    [Fact]public void A_reversed_accepted_clock_makes_the_current_series_unavailable()
    {
        var state=Start(CompanionTaskKind.Habit);state=Apply(state,WorkspaceOperation.UpdateTask,"2026-10-28T00:00:00Z",new(Text:"later witness"));state=Apply(state,WorkspaceOperation.UpdateTask,"2026-10-27T01:00:00Z",new(Text:"clock moved back"));var result=WorkspaceActivityStreaks.Evaluate(state,Filter(state,"2026-10-27","2026-10-29T12:00:00Z"));Assert.Null(result.CurrentStreak);Assert.Equal("unavailable",result.CurrentQuality);Assert.Equal("lowerBound",result.LongestQuality);Assert.Contains(result.Items,r=>r.Reason=="clock_order_unknown");
    }

    [Fact]public void Missing_historical_goal_snapshots_are_labelled_as_current_task_fallback()
    {
        var state=Examples().Single(e=>e.Name=="legacy-positive-evidence-retains-a-lower-bound").Snapshot;state=state with{Commands=[],Events=[]};Assert.True(WorkspaceJournalValidation.IsValid(state));var result=WorkspaceActivityStreaks.Evaluate(state,Filter(state,"2026-10-27","2026-10-29T12:00:00Z"));Assert.Equal("currentTask",result.ModeSource);Assert.Equal("lowerBound",result.CurrentQuality);Assert.Null(result.LifetimeBest);
    }

}
